#!/usr/bin/env python3
"""wordstat 的测试：覆盖 count_words / top_n 及边界情况。

全部通过时打印 ALL TESTS PASSED。
"""

import wordstat


def test_count_words_basic():
    assert wordstat.count_words("hello world hello") == {"hello": 2, "world": 1}


def test_count_words_case_insensitive():
    assert wordstat.count_words("Hello HELLO hello") == {"hello": 3}
    assert wordstat.count_words("The the THE") == {"the": 3}


def test_count_words_strip_punctuation():
    assert wordstat.count_words("hello, world!") == {"hello": 1, "world": 1}
    assert wordstat.count_words("...hello... (world)") == {"hello": 1, "world": 1}
    assert wordstat.count_words("'quoted' \"quoted\"") == {"quoted": 2}
    # 纯标点 token 剥后为空，不计数
    assert wordstat.count_words("hello ... !!!") == {"hello": 1}


def test_count_words_empty():
    assert wordstat.count_words("") == {}
    assert wordstat.count_words("   \n\t  ") == {}


def test_count_words_newlines_and_whitespace():
    assert wordstat.count_words("one\ntwo\tthree\none") == {
        "one": 2, "two": 1, "three": 1}


def test_top_n_ordering():
    counts = {"a": 1, "b": 3, "c": 3, "d": 2}
    assert wordstat.top_n(counts, 2) == [("b", 3), ("c", 3)]
    # 次数降序；同次数按词升序
    assert wordstat.top_n(counts, 10) == [("b", 3), ("c", 3), ("d", 2), ("a", 1)]


def test_top_n_more_than_words():
    assert wordstat.top_n({"x": 1, "y": 2}, 100) == [("y", 2), ("x", 1)]


def test_top_n_empty():
    assert wordstat.top_n({}, 3) == []
    assert wordstat.top_n({}, 0) == []


def test_top_n_zero_or_negative():
    counts = {"a": 1, "b": 2}
    assert wordstat.top_n(counts, 0) == []
    assert wordstat.top_n(counts, -1) == []


def main():
    tests = [
        test_count_words_basic,
        test_count_words_case_insensitive,
        test_count_words_strip_punctuation,
        test_count_words_empty,
        test_count_words_newlines_and_whitespace,
        test_top_n_ordering,
        test_top_n_more_than_words,
        test_top_n_empty,
        test_top_n_zero_or_negative,
    ]
    for test in tests:
        test()
    print("ALL TESTS PASSED")


if __name__ == "__main__":
    main()
